import{c as e,Q as n,J as i,h as l,e as s,l as r,m as o,k as c}from"./chunks/framework.WgZQdPFo.js";const b=JSON.parse('{"title":"Candle & Soap Cost Calculator","description":"Free online candle and artisan soap cost calculator for craft makers. Calculate soy wax grams, fragrance oil load %, crackling wicks, amber jars, and craft labor.","frontmatter":{"title":"Candle & Soap Cost Calculator","description":"Free online candle and artisan soap cost calculator for craft makers. Calculate soy wax grams, fragrance oil load %, crackling wicks, amber jars, and craft labor.","tags":["Tools","Economics","Crafts & Handmade"],"head":[["meta",{"property":"og:title","content":"Candle & Soap Cost Calculator | OmniCraft ERP"}],["meta",{"property":"og:description","content":"Free online candle and artisan soap cost calculator for craft makers: soy wax grams, fragrance load %, wick, jar, packaging, labor rate, and Excel template."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://omnicraft-erp.com/calculators/candle-cost-calculator"}],["meta",{"property":"og:image","content":"https://omnicraft-erp.com/img/en/calculators/candle-cost-calculator-og.webp"}],["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@graph\\": [\\n    {\\n      \\"@type\\": \\"WebApplication\\",\\n      \\"name\\": \\"Candle & Soap Cost Calculator\\",\\n      \\"applicationCategory\\": \\"BusinessApplication\\",\\n      \\"operatingSystem\\": \\"All\\",\\n      \\"browserRequirements\\": \\"Requires JavaScript. Requires HTML5.\\",\\n      \\"offers\\": {\\n        \\"@type\\": \\"Offer\\",\\n        \\"price\\": \\"0\\",\\n        \\"priceCurrency\\": \\"USD\\"\\n      },\\n      \\"image\\": \\"https://omnicraft-erp.com/img/en/calculators/candle-cost-calculator-og.webp\\",\\n      \\"description\\": \\"Free online candle and artisan soap cost calculator for craft makers and small studio chandlers.\\"\\n    },\\n    {\\n      \\"@type\\": \\"Article\\",\\n      \\"headline\\": \\"Candle & Soap Cost Calculator\\",\\n      \\"description\\": \\"Free online candle and artisan soap cost calculator for craft makers. Calculate soy wax grams, fragrance oil load %, crackling wicks, amber jars, and craft labor.\\",\\n      \\"inLanguage\\": \\"en-US\\",\\n      \\"mainEntityOfPage\\": \\"https://omnicraft-erp.com/calculators/candle-cost-calculator\\",\\n      \\"image\\": \\"https://omnicraft-erp.com/img/en/calculators/candle-cost-calculator-og.webp\\",\\n      \\"datePublished\\": \\"2026-10-11\\",\\n      \\"dateModified\\": \\"2026-10-19\\",\\n      \\"author\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"OmniCraft ERP\\",\\n        \\"url\\": \\"https://omnicraft-erp.com/\\"\\n      },\\n      \\"publisher\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"OmniCraft ERP\\",\\n        \\"url\\": \\"https://omnicraft-erp.com/\\",\\n        \\"logo\\": {\\n          \\"@type\\": \\"ImageObject\\",\\n          \\"url\\": \\"https://omnicraft-erp.com/logo.svg\\"\\n        }\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"BreadcrumbList\\",\\n      \\"itemListElement\\": [\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 1,\\n          \\"name\\": \\"Home\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 2,\\n          \\"name\\": \\"Cost Calculators\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/calculators/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 3,\\n          \\"name\\": \\"Candle & Soap Cost Calculator\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/calculators/candle-cost-calculator\\"\\n        }\\n      ]\\n    }\\n  ]\\n}\\n"]]},"headers":[],"relativePath":"calculators/candle-cost-calculator.md","filePath":"calculators/candle-cost-calculator.md"}'),p={name:"calculators/candle-cost-calculator.md"};function d(h,a,u,g,m,f){const t=n("CostCalculator");return i(),l("div",null,[a[0]||(a[0]=s("div",{class:"article-breadcrumb"},[s("a",{href:"/calculators/"},"← All Calculators")],-1)),a[1]||(a[1]=s("h1",{id:"candle-soap-cost-calculator",tabindex:"-1"},[r("Candle & Soap Cost Calculator "),s("a",{class:"header-anchor",href:"#candle-soap-cost-calculator","aria-label":'Permalink to "Candle & Soap Cost Calculator"'},"​")],-1)),a[2]||(a[2]=s("p",null,"Interactive unit cost calculator for artisan candles, diffusers, and handcrafted soap: calculate net wax weight, fragrance oil load, glassware, wicks, packaging, and craft studio labor.",-1)),o(t,{lang:"en",preset:"candle"}),a[3]||(a[3]=c('<div class="satellites-nav-block"><div class="satellites-nav-title"><svg class="satellite-title-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="2" width="16" height="20" rx="2"></rect><line x1="8" y1="6" x2="16" y2="6"></line><line x1="16" y1="14" x2="16" y2="18"></line><path d="M16 10h.01"></path><path d="M12 10h.01"></path><path d="M8 10h.01"></path><path d="M12 14h.01"></path><path d="M8 14h.01"></path><path d="M12 18h.01"></path><path d="M8 18h.01"></path></svg><span>Other Cost Calculators:</span></div><div class="satellites-nav-grid"><a href="/calculators/product-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg></span><div class="satellite-info"><strong>Universal Product Cost Calculator</strong><span>For any batch or custom manufactured item: materials, scrap, BOM, and labor</span></div><span class="satellite-arrow">→</span></a><a href="/calculators/3d-print-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg></span><div class="satellite-info"><strong>3D Printing Cost Calculator</strong><span>Filament, support waste, heat-set M3 threaded inserts, and printer depreciation</span></div><span class="satellite-arrow">→</span></a><a href="/calculators/dish-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3c-4.97 0-9 4.03-9 9h18c0-4.97-4.03-9-9-9z"></path><path d="M2 12h20v2a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4v-2z"></path><line x1="12" y1="2" x2="12" y2="3"></line><line x1="4" y1="21" x2="20" y2="21"></line></svg></span><div class="satellite-info"><strong>Recipe &amp; Culinary Cost Calculator</strong><span>Yield sheets, gross/net weights, thermal shrinkage, and target food cost %</span></div><span class="satellite-arrow">→</span></a><a href="/calculators/cake-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-8a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8"></path><path d="M4 16s.5-1 2-1 2.5 2 4 2 2.5-2 4-2 2.5-2 4-2 2.5-2 4 2 2-1 2-1"></path><path d="M2 21h20"></path><line x1="7" y1="8" x2="7" y2="11"></line><line x1="12" y1="8" x2="12" y2="11"></line><line x1="17" y1="8" x2="17" y2="11"></line></svg></span><div class="satellite-info"><strong>Custom Cake &amp; Bakery Cost Calculator</strong><span>For artisan bakers: ingredients, sponge bake loss, decor, cake drums, and packaging</span></div><span class="satellite-arrow">→</span></a><a href="/calculators/beauty-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m12 3-1.9 5.8a2 2 0 0 1-1.3 1.3L3 12l5.8 1.9a2 2 0 0 1 1.3 1.3L12 21l1.9-5.8a2 2 0 0 1 1.3-1.3L21 12l-5.8-1.9a2 2 0 0 1-1.3-1.3L12 3z"></path></svg></span><div class="satellite-info"><strong>Beauty Salon &amp; Manicure Cost Calculator</strong><span>Gel polish coats, disposable kits, autoclave sterilization, and booth rent</span></div><span class="satellite-arrow">→</span></a><a href="/calculators/leather-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg></span><div class="satellite-info"><strong>Leathercraft Cost Calculator</strong><span>Usable hide area, cutting offcuts, hardware, and saddle stitch labor</span></div><span class="satellite-arrow">→</span></a></div></div><hr><h2 id="candle-batch-verdict-interpreting-financial-health" tabindex="-1">Candle Batch Verdict: Interpreting Financial Health <a class="header-anchor" href="#candle-batch-verdict-interpreting-financial-health" aria-label="Permalink to &quot;Candle Batch Verdict: Interpreting Financial Health&quot;">​</a></h2><p>The calculator classifies your candle production batch into three financial viability zones:</p><h3 id="_1-margin-illusion-unprofitable-batch" tabindex="-1">1. Margin Illusion (Unprofitable Batch) <a class="header-anchor" href="#_1-margin-illusion-unprofitable-batch" aria-label="Permalink to &quot;1. Margin Illusion (Unprofitable Batch)&quot;">​</a></h3><p>The full unit cost of the pour (wax + premium fragrance oil + glassware + shrink scrap allowance + wooden wick + labor time) exceeds your target wholesale or retail price.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>What is happening:</strong> the maker is effectively giving away concentrated fragrance oil for free and subsidizing shipping transit breakage out of their own pocket.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>What to do:</strong> recalibrate fragrance load to an optimal 8%, procure soy wax flakes in bulk bags (45–55 lbs / 20–25 kg), or raise retail pricing to reflect true artisan craftsmanship.</div></li></ul><h3 id="_2-hidden-risk-underestimating-shrinkage-touch-up-hours" tabindex="-1">2. Hidden Risk (Underestimating Shrinkage &amp; Touch-up Hours) <a class="header-anchor" href="#_2-hidden-risk-underestimating-shrinkage-touch-up-hours" aria-label="Permalink to &quot;2. Hidden Risk (Underestimating Shrinkage &amp; Touch-up Hours)&quot;">​</a></h3><p>The batch is technically in the black, but your effective hourly earning rate drops below standard minimum shop wages ($10–$12/hour).</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>What is happening:</strong> profit is quietly eroded by lengthy heat gun top-offs, remelting frosted surfaces, and slow, manual label alignment.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>What to do:</strong> stabilize cooling temperatures in your pouring room to eliminate frosting defects and streamline batch packaging workflows.</div></li></ul><h3 id="_3-healthy-artisan-batch" tabindex="-1">3. Healthy Artisan Batch <a class="header-anchor" href="#_3-healthy-artisan-batch" aria-label="Permalink to &quot;3. Healthy Artisan Batch&quot;">​</a></h3><p>The batch fully amortizes soy wax with an 8% pitcher scrap allowance, covers premium fragrance and amber glassware, guarantees the chandler $25–$40/hour in craft labor, and leaves at least 25% net operating margin to fund seasonal scent R&amp;D.</p><hr><h2 id="candle-soap-economics-4-cost-traps-for-craft-makers" tabindex="-1">Candle &amp; Soap Economics: 4 Cost Traps for Craft Makers <a class="header-anchor" href="#candle-soap-economics-4-cost-traps-for-craft-makers" aria-label="Permalink to &quot;Candle &amp; Soap Economics: 4 Cost Traps for Craft Makers&quot;">​</a></h2><p>Candle making seems deceptive in its simplicity: melt soy wax flakes, stir in fragrance oil, pour into an amber glass jar with a centered wick, and mark it up by 300%. Yet when makers audit their end-of-year accounts, packaging, marketplace seller fees, and expensive fragrance loss often consume all net profit.</p><p>Here are the four key overhead factors every artisan must track:</p><h3 id="_1-jar-fluid-volume-vs-net-wax-weight" tabindex="-1">1. Jar Fluid Volume vs Net Wax Weight <a class="header-anchor" href="#_1-jar-fluid-volume-vs-net-wax-weight" aria-label="Permalink to &quot;1. Jar Fluid Volume vs Net Wax Weight&quot;">​</a></h3><p>The specific gravity of melted natural wax is lower than water (approx. <strong>0.86–0.90 g/ml</strong>):</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Fluid Volume Discrepancy:</strong> a vessel rated at &quot;200 ml&quot; does not hold 200 grams of wax. It typically accommodates only 160 to 170 grams of blended wax and fragrance.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Tied-up Working Capital:</strong> purchasing wax assuming 1:1 weight-to-volume ties up cash flow in excess unsold raw material.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Batch Compounding Error:</strong> across a 50-candle pour, miscalculating wax density leads to purchasing 1.5–2 kg of excess wax flakes.</div></li></ul><h3 id="_2-fragrance-oil-load-and-the-can-of-paint-rule-mac" tabindex="-1">2. Fragrance Oil Load and the &quot;Can of Paint&quot; Rule (MAC) <a class="header-anchor" href="#_2-fragrance-oil-load-and-the-can-of-paint-rule-mac" aria-label="Permalink to &quot;2. Fragrance Oil Load and the &quot;Can of Paint&quot; Rule (MAC)&quot;">​</a></h3><p>Premium fragrance oils (CandleScience, Makesy, French perfumeries) constitute <strong>35% to 50% of direct production costs</strong>:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Standard Scent Load:</strong> for maximum cold and hot scent throw, recipes require 8% to 10% fragrance oil calculated strictly against dry wax mass.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>High Cost per Drop:</strong> a 160 g candle requires 16 g of scent oil. At wholesale prices of \\$30–\\$40 per 16 oz, fragrance alone costs **\\$1.80 to \\$2.50 per unit**.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>The &quot;Can of Paint&quot; Rule (MAC):</strong> a 16 oz bottle is dispensed across batches. Without tracking moving average cost, margins rapidly erode.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Volatile Flash Points:</strong> adding fragrance oil above 185°F (85°C) flashes off delicate top notes, wasting expensive perfume.</div></li></ul><h3 id="_3-pitcher-residue-and-thermal-shrinkage-8–12" tabindex="-1">3. Pitcher Residue and Thermal Shrinkage (8–12%) <a class="header-anchor" href="#_3-pitcher-residue-and-thermal-shrinkage-8–12" aria-label="Permalink to &quot;3. Pitcher Residue and Thermal Shrinkage (8–12%)&quot;">​</a></h3><p>Molten wax cannot be fully poured without leaving residue behind:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Pitcher Cling:</strong> 10 to 25 grams of wax inevitably solidifies against the walls and base of the pouring pitcher per pour batch.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Cooling Cavities &amp; Sinkholes:</strong> natural plant waxes shrink as they cool. Surface sinkholes require secondary top-offs or heat-gun touch-ups.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Polymorphic Frosting:</strong> drafts cause white crystalline frosting patches, downgrading aesthetic candle grades.</div></li></ul><p>Production scrap allowances for wax must be set to <strong>at least 8%</strong>.</p><h3 id="_4-glassware-packaging-and-the-lightbulb-over-the-workbench-rule" tabindex="-1">4. Glassware, Packaging, and the &quot;Lightbulb over the Workbench&quot; Rule <a class="header-anchor" href="#_4-glassware-packaging-and-the-lightbulb-over-the-workbench-rule" aria-label="Permalink to &quot;4. Glassware, Packaging, and the &quot;Lightbulb over the Workbench&quot; Rule&quot;">​</a></h3><p>A premium artisanal candle is an assembly of fragile components:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>UV-Blocking Amber Glass Jar &amp; Lid:</strong> protects delicate essential oils from sunlight degradation (\\$1.20–\\$1.80).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Crackling Wooden Wick &amp; Metal Anchor Clip:</strong> delivers an ambient fireplace crackle and flat flame (\\$0.30–\\$0.50).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>High-Temp Wick Adhesive Dot (Glue Dot):</strong> keeps the wick firmly anchored during hot pours (\\$0.15).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Mandatory Safety Caution Label:</strong> fire safety compliance sticker with burn warnings for the jar base (\\$0.15).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Rigid Presentation Tube or Gift Shipper Box:</strong> prevents transit glass breakage during postal handling (\\$1.00–\\$1.50).</div></li></ul><p>In addition, wax melters, heat guns for surface smoothing, and digital scales draw continuous electricity. This is the workshop <strong>&quot;Lightbulb over the Workbench&quot; rule</strong>: fixed studio overhead and tool wear add <strong>$0.50 to $1.20 in operational costs to every candle produced</strong>.</p><hr><div class="price-breakdown-card"><div class="breakdown-header"><span class="breakdown-tag">Candle Cost Anatomy</span><h3 class="breakdown-title">What Makes Up the Retail Price of a Craft Candle</h3><p class="breakdown-desc">Typical financial structure for a healthy artisanal 8 oz / 200 ml soy candle in amber glass:</p></div><div class="breakdown-bar-track"><div class="breakdown-segment" style="width:45%;background:#3b82f6;" data-tooltip="Wax &amp; Fragrance: 45%"><span class="seg-label">Wax &amp; Fragrance 45%</span></div><div class="breakdown-segment" style="width:25%;background:#f59e0b;" data-tooltip="Jar &amp; Box: 25%"><span class="seg-label">Jar &amp; Box 25%</span></div><div class="breakdown-segment" style="width:15%;background:#10b981;" data-tooltip="Labor: 15%"><span class="seg-label">Labor 15%</span></div><div class="breakdown-segment" style="width:15%;background:#8b5cf6;" data-tooltip="Margin: 15%"><span class="seg-label">Margin 15%</span></div></div><div class="breakdown-grid"><div class="breakdown-item item-cost"><div class="item-head"><strong>1. Raw Materials &amp; Scents</strong><span class="item-badge">40–50%</span></div><p class="item-summary">Direct consumable ingredients per pour:</p><ul class="item-list"><li>Soy or coconut wax with +8% pitcher cling allowance</li><li>Pure fragrance oil at 8–10% recommended scent load</li><li>FSC wooden or cotton wick and metal centering clip</li></ul></div><div class="breakdown-item item-tax"><div class="item-head"><strong>2. Vessels &amp; Presentation</strong><span class="item-badge">20–25%</span></div><p class="item-summary">Branding and transit protection:</p><ul class="item-list"><li>Amber apothecary glass jar with airtight seal lid</li><li>Soft-touch water-resistant label and warning base sticker</li><li>Rigid cardboard gift tube or corrugated shipper box</li></ul></div><div class="breakdown-item item-margin"><div class="item-head"><strong>3. Labor &amp; Workshop Fund</strong><span class="item-badge">25–35%</span></div><p class="item-summary">Artisan compensation and studio sustainability:</p><ul class="item-list"><li>Melting, fragrance blending, pouring, and heat-gun top-off</li><li>Wax melter electricity, thermometer depreciation, and rent</li><li>Net chandler profit margin to finance new seasonal scent lines</li></ul></div></div></div><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Cost Formula</span><div class="formula-heading">Comprehensive Unit Candle Batch Cost Formula</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">C<sub>candle</sub></span><span class="math-op">=</span><span class="math-group">[</span><span class="math-var">M<sub>wax</sub></span><span class="math-op">×</span> 1.08 <span class="math-op">×</span><span class="math-var">P<sub>wax</sub></span><span class="math-group">]</span><span class="math-op">+</span><span class="math-group">(</span><span class="math-var">M<sub>oil</sub></span> <span class="math-op">×</span> <span class="math-var">P<sub>oil</sub></span><span class="math-group">)</span><span class="math-op">+</span><span class="math-var">P<sub>jar</sub></span><span class="math-op">+</span><span class="math-var">P<sub>wick</sub></span><span class="math-op">+</span><span class="math-var">P<sub>pack</sub></span><span class="math-op">+</span><span class="math-group">(</span><span class="math-var">T</span> <span class="math-op">×</span> <span class="math-var">R<sub>hour</sub></span><span class="math-group">)</span><span class="math-op">+</span><span class="math-var">O<sub>shop</sub></span></div></div><div class="formula-vars-heading">Variable Definitions:</div><div class="formula-vars-grid"><div class="var-chip"><span class="var-code">M<sub>wax</sub> × 1.08</span><span class="var-text">Net wax mass multiplied by 1.08 to cover 8% pitcher cling residue</span></div><div class="var-chip"><span class="var-code">M<sub>oil</sub> × P<sub>oil</sub></span><span class="var-text">Fragrance oil mass (8–10% of wax weight) multiplied by price per gram</span></div><div class="var-chip"><span class="var-code">P<sub>jar</sub></span><span class="var-text">Apothecary glass container, lid, and bottom warning safety label</span></div><div class="var-chip"><span class="var-code">P<sub>pack</sub></span><span class="var-text">Gift tube, corrugated box, crinkle paper, and custom branding label</span></div><div class="var-chip"><span class="var-code">T × R<sub>hour</sub></span><span class="var-text">Labor duration (melting, pouring, top-off) multiplied by hourly wage</span></div><div class="var-chip"><span class="var-code">O<sub>shop</sub></span><span class="var-text">Wax melter electricity, thermometer depreciation, and studio overhead</span></div></div></div><hr><h2 id="real-world-unit-economics-the-guesstimate-trap-vs-studio-costing" tabindex="-1">Real-World Unit Economics: The &quot;Guesstimate&quot; Trap vs Studio Costing <a class="header-anchor" href="#real-world-unit-economics-the-guesstimate-trap-vs-studio-costing" aria-label="Permalink to &quot;Real-World Unit Economics: The &quot;Guesstimate&quot; Trap vs Studio Costing&quot;">​</a></h2><p>To see where artisan candle maker profits vanish, let&#39;s dissect the real-world commercial batch modeled in our pre-configured Excel workbook: a <strong>200 ml (6.8 fl oz) amber glass scented candle</strong> with an organic crackling wood wick, 10% premium fragrance oil load, and an embossed luxury gift tube.</p><p>Net wax required for filling is <strong>160 g</strong> (gross wax melted with an 8% pitcher cling buffer is <strong>172.8 g</strong>), fragrance oil load is <strong>16 g</strong>, and artisan active craft time is <strong>0.4 hours</strong> (24 minutes: jar preparation, degreasing, wick seating, wax melting, precision fragrance incorporation at 175–185 °F, pouring, centering, and heat gun surface finishing):</p><div class="comparison-matrix-wrapper"><table class="craft-comparison-table"><thead><tr><th style="width:34%;">Cost Item / Technological Spec</th><th style="width:33%;">Beginner &quot;Guesstimate&quot;</th><th style="width:33%;" class="col-highlight"><div class="col-highlight-badge">True Costing</div> Artisan Studio Recipe Card </th></tr></thead><tbody><tr><td><strong>1. Premium Soy Wax (Golden Wax 464, 160 g net +8% = 172.8 g)</strong></td><td><span class="status-chip chip-amber">\\$2.40</span><span class="chip-sub">Calculated as 160 g dry weight without pitcher cling</span></td><td class="col-highlight"><span class="status-chip chip-green">\\$2.59</span><span class="chip-sub">With +8% wall cling residue and pouring shrinkage accounted</span></td></tr><tr><td><strong>2. Premium Fragrance Oil (16 g, 10% fragrance load)</strong></td><td><span class="status-chip chip-amber">\\$1.50</span><span class="chip-sub">&quot;Added a few drops by eye from bottle&quot;</span></td><td class="col-highlight"><span class="status-chip chip-green">\\$3.20</span><span class="chip-sub">16 g certified luxury fragrance oil at Moving Average Cost (MAC)</span></td></tr><tr><td><strong>3. 200 ml Amber Vessel with Lid &amp; Wood Wick with Clip</strong></td><td><span class="status-chip chip-amber">\\$1.80</span><span class="chip-sub">Cheap wholesale jar without lid or wick assembly</span></td><td class="col-highlight"><span class="status-chip chip-green">\\$2.80</span><span class="chip-sub">Amber glass with metal lid (\\$2.20) + crackling wood wick &amp; clip (\\$0.60)</span></td></tr><tr><td><strong>4. Pouring Consumables &amp; Safety (glue dot, warning label)</strong></td><td><span class="status-chip chip-gray">\\$0.00</span><span class="chip-sub">&quot;Wick stickers and labels cost nothing&quot;</span></td><td class="col-highlight"><span class="status-chip chip-green">\\$0.45</span><span class="chip-sub">High-temp wick glue dot (\\$0.25) + bottom safety caution label (\\$0.20)</span></td></tr><tr><td><strong>5. Packaging (embossed gift tube, scent story card)</strong></td><td><span class="status-chip chip-gray">\\$0.00</span><span class="chip-sub">&quot;Handed out in a thin paper bag&quot;</span></td><td class="col-highlight"><span class="status-chip chip-green">\\$1.80</span><span class="chip-sub">Rigid kraft tube with crinkle bed for safe transit packaging</span></td></tr><tr><td><strong>6. Artisan Craft Labor (0.4 h × \\$12/h) &amp; Equipment Wear</strong></td><td><span class="status-chip chip-gray">\\$0.00</span><span class="chip-sub">&quot;My labor is free because it&#39;s a creative hobby&quot;</span></td><td class="col-highlight"><span class="status-chip chip-green">\\$5.04</span><span class="chip-sub">0.4 h craft labor (\\$4.80) + melter power &amp; heat gun depreciation (\\$0.24)</span></td></tr><tr><td><strong>7. Total Unit Cost (finished 200 ml candle in tube)</strong></td><td><span class="status-chip chip-amber">\\$5.70</span><span class="chip-sub">Imaginary bill-of-materials cost</span></td><td class="col-highlight"><span class="status-chip chip-green">\\$15.88</span><span class="chip-sub">Materials &amp; vessel (\\$9.04) + Packaging (\\$1.80) + Labor &amp; overhead (\\$5.04)</span></td></tr><tr><td><strong>Financial Outcome at \\$24.00 Retail Price</strong></td><td><span class="status-chip chip-gray">Illusion of +\\$18.30 profit</span><span class="chip-sub">If sold on Etsy for \\$14.00 — net loss of -\\$1.88 per candle</span></td><td class="col-highlight"><span class="status-chip chip-green">Net Profit +\\$8.12</span><span class="chip-sub">At \\$24.00 retail price (net profit margin 33.8%, status 🟢 Healthy order)</span></td></tr></tbody></table></div><hr><h2 id="download-ready-to-use-candle-cost-calculation-excel-template" tabindex="-1">Download Ready-to-Use Candle Cost Calculation Excel Template <a class="header-anchor" href="#download-ready-to-use-candle-cost-calculation-excel-template" aria-label="Permalink to &quot;Download Ready-to-Use Candle Cost Calculation Excel Template&quot;">​</a></h2><p>For offline batch costing and recipe planning, we packaged all candle making math into a branded, pre-configured spreadsheet. Download it and tailor the fragrance load percentages directly to your workshop recipes:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Automatic vessel volume conversion:</strong> converts fluid container capacity (ml) into dry wax weight (g) calibrated to vegetable wax density 0.88.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Fragrance load calculator (6% to 12%):</strong> calculates precise fragrance oil grams based strictly on net dry wax weight.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Pitcher cling allowance (+8%):</strong> factors in residue left on melting pitchers, stirrers, and temperature probes.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Automated financial traffic light:</strong> instant health check on net margin to protect studio cash flow from hidden losses.</div></li></ul><div class="download-banner"><div class="download-info"><div class="download-title">Candle &amp; Diffuser Cost Calculation Template</div><div class="download-desc">Excel (.xlsx) format — fully compatible with Microsoft Excel, LibreOffice, and Google Sheets. No macros required.</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;"><a href="/downloads/omnicraft_candle_cost_calculator_en.xlsx" download="OmniCraft_Candle_Cost_Calculator.xlsx" class="vp-button brand" data-omni-event="calc_article_download_xlsx_en"> Excel Template (.xlsx) </a></div></div><hr><h2 id="related-production-knowledge-cluster" tabindex="-1">Related Production Knowledge Cluster <a class="header-anchor" href="#related-production-knowledge-cluster" aria-label="Permalink to &quot;Related Production Knowledge Cluster&quot;">​</a></h2><ul><li><a href="/articles/pricing-and-margins">Pricing, Markup, and Profit Margin: How to Price Your Products</a> — complete breakdown of wholesale vs retail pricing formulas and why markup is not profit margin.</li><li><a href="/articles/cost-calculation-software">Cost Calculation Software: Why Excel and Legacy ERP Fail Small Workshops</a> — comparing manual spreadsheets with dedicated craft studio inventory management software.</li></ul><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><div class="craft-faq-container"><details class="craft-faq-card"><summary class="craft-faq-summary"><span class="faq-q-text">How do you accurately convert container volume in milliliters to wax weight in grams?</span><span class="faq-chevron"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"></polyline></svg></span></summary><div class="craft-faq-body"><p>Never treat fluid milliliters as grams: natural vegetable waxes have a lower specific gravity than water (ρ ≈ 0.86–0.90 g/ml). To calculate required dry wax mass, use the standard density conversion formula:</p><div class="faq-formula-card"><div class="faq-formula-badge">Wax Mass Formula</div><div class="faq-formula-eq"><span class="math-var">M<sub>wax</sub></span><span class="math-op">=</span><span class="math-var">V<sub>jar</sub></span><span class="math-op">×</span><span class="math-var">ρ<sub>wax</sub></span><span class="math-op">×</span><span class="math-group">(</span> 1 <span class="math-op">−</span><span class="math-fraction"><span class="math-num">Load<sub>frag %</sub></span><span class="math-denom">100</span></span><span class="math-group">)</span></div></div><p>For a standard <strong>200 ml container</strong> with soy wax density of <strong>0.88 g/ml</strong> and a <strong>10% fragrance load</strong>, net dry wax required is: <code>200 × 0.88 × (1 − 0.10) = 158.4 grams</code> of wax plus <code>15.8 grams</code> of fragrance oil (total finished candle fill: ~174 g).</p></div></details><details class="craft-faq-card"><summary class="craft-faq-summary"><span class="faq-q-text">Should fragrance oil percentage be calculated from wax weight or total candle weight?</span><span class="faq-chevron"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"></polyline></svg></span></summary><div class="craft-faq-body"><p>Leading global fragrance oil and wax manufacturers (CandleScience, Makesy) calibrate testing and safety technical datasheets strictly <strong>as a percentage of dry wax weight</strong>:</p><div class="faq-formula-card"><div class="faq-formula-badge">Fragrance Load Formula</div><div class="faq-formula-eq"><span class="math-var">M<sub>frag</sub></span><span class="math-op">=</span><span class="math-var">M<sub>wax</sub></span><span class="math-op">×</span><span class="math-fraction"><span class="math-num">Load<sub>%</sub></span><span class="math-denom">100</span></span></div></div><p>If you weigh out <strong>160 g of dry soy wax</strong> flakes and your fragrance oil load target is <strong>10%</strong>, you must measure exactly: <code>160 × 0.10 = 16.0 grams</code> of fragrance oil. Calculating fragrance load against finished candle weight underdoses scent concentration, reducing hot throw performance.</p></div></details><details class="craft-faq-card"><summary class="craft-faq-summary"><span class="faq-q-text">How do you calculate the break-even point for a craft candle studio?</span><span class="faq-chevron"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"></polyline></svg></span></summary><div class="craft-faq-body"><p>The break-even point establishes the minimum number of candles your studio must sell each month to cover fixed operational costs (studio rent, insurance, photography, utilities):</p><div class="faq-formula-card"><div class="faq-formula-badge">Break-Even Unit Formula</div><div class="faq-formula-eq"><span class="math-var">Q<sub>min</sub></span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">O<sub>fixed</sub></span><span class="math-denom">P<sub>retail</sub> − S<sub>var</sub></span></span></div></div><p>If monthly studio overhead is <strong>\\$600/month</strong>, your signature candle retails for <strong>\\$24.00</strong>, and direct variable unit cost (wax, oil, vessel, box) is <strong>\\$10.84</strong>, contribution margin per candle is: <code>\\$24.00 − \\$10.84 = \\$13.16</code>. Minimum studio break-even volume: <code>600 / 13.16 = 45.6</code> → <strong>46 candles per month</strong>.</p></div></details><details class="craft-faq-card"><summary class="craft-faq-summary"><span class="faq-q-text">How should candle makers account for sales/revenue tax: deducted from profits or added to candle price?</span><span class="faq-chevron"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"></polyline></svg></span></summary><div class="craft-faq-body"><p>Tax is assessed on the <strong>gross retail price of each candle or diffuser</strong>. Deducting it from workshop net profit or pouring labor compensation is a frequent beginner mistake.</p><div class="faq-formula-card"><div class="faq-formula-badge">Candle Pricing Tax Formula</div><div class="faq-formula-eq"><span class="math-var">S<sub>total</sub></span><span class="math-op">=</span><span class="math-var">S<sub>prod</sub></span><span class="math-op">+</span><span class="math-group">(</span><span class="math-var">P<sub>candle</sub></span><span class="math-op">×</span><span class="math-fraction"><span class="math-num">Tax %</span><span class="math-denom">100</span></span><span class="math-group">)</span></div></div><p>On a jar candle retailing for <strong>$25</strong>, a 5% tax equals <strong>$1.25</strong>. This tax is layered into the price: <code>$14.50 production + $1.25 tax = $15.75 landed cost</code>. The customer pays the tax, ensuring your pouring labor pay and studio reinvestment margin remain fully intact.</p></div></details></div><hr><div class="cta-erp-box"><div class="cta-erp-content"><h3>Tired of recalculating scent loads and wax batches on scraps of paper?</h3><p>OmniCraft ERP is a local-first software built for craft studios. Store proprietary candle recipes with exact fragrance ratios, track expensive perfume oils and soy wax inventory by moving average cost (MAC), automatically deduct jars and wicks, and analyze actual batch margins offline.</p><a href="/" class="vp-button brand" data-omni-event="candle_article_cta_home_en"> Try OmniCraft ERP Free → </a></div></div>',51))])}const w=e(p,[["render",d]]);export{b as __pageData,w as default};
